{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C02","C03","C26","C16","C01","C10","C23","C36","C12","C15","C39","C27","C07","C14","C33","C35"],
  "contradictory_card_ids": ["C22","C40","C25","C31"],
  "prediction_basis_card_ids": ["C02","C03","C26","C16","C01","C10","C23","C36","C12","C15","C39","C27","C07","C14","C33","C35"],
  "claims": [
    {
      "claim": "The query is a quaternary ammonium iboga-type alkaloid with an N-methyl indoline; the most direct transferable low-F evidence is ipratropium, a permanently charged quaternary ammonium antimuscarinic, with absolute oral bioavailability 2.3% (10 mg), 2.0% (2 mg), and 3.27% (20 mg) and low bioavailability attributed partly to intestinal active secretion.",
      "card_ids": ["C02","C03","C26","C16"]
    },
    {
      "claim": "Physostigmine, an N-methyl indoline alkaloid, has oral bioavailability 1-5% and mean absolute F 3% for an oral solution; L2 confirms 1 to <5% from AUC comparison, while the 23% and 25.3% values are less reliable outliers.",
      "card_ids": ["C01","C10","C23","C36","C22","C40"]
    },
    {
      "claim": "Lisuride, an ergoline alkaloid, has oral bioavailability about 10% after 100 µg and 10-20% in a review; L2 shows similar bioavailability across age groups, supporting consistently low F.",
      "card_ids": ["C12","C15","C39","C27"]
    },
    {
      "claim": "Pentazocine mean oral bioavailability is 18% from 100 mg tablets; L2 reports 0.18 ± 0.05 in a control group and low availability in solution, all below the 20% threshold.",
      "card_ids": ["C07","C14","C33","C35"]
    },
    {
      "claim": "L3 oral AUC/Cmax records concern unrelated chemotypes and report exposure parameters without absolute oral bioavailability values; they do not provide threshold-relevant evidence for the quaternary ammonium iboga-type query.",
      "card_ids": ["C41","C42","C43","C44","C45","C46","C47","C48","C49","C50","C51","C52"]
    },
    {
      "claim": "L4 solubility/dissolution records are mostly for unrelated chemotypes; C64 shows physostigmine salicylate is highly water-soluble (13.3 mg/mL), indicating physostigmine's low F is not solubility-limited, but this does not provide query-specific permeability or F evidence and does not change the low prediction.",
      "card_ids": ["C64"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C53","C54","C55","C56","C57","C58","C59","C60","C61","C62","C63","C64"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the query molecule.",
    "No query-specific permeability, efflux, or intestinal metabolism data are available; L4 contains only solubility/dissolution records.",
    "The explicit [N@+] quaternary ammonium in the SMILES conflicts with the computed neutral fraction of 0.98; if the permanent cation is real, the favorable logD/TPSA-based prior is not reliable.",
    "Transfer from ipratropium, physostigmine, lisuride, and pentazocine is analog-based; species, formulation, dose, and route differences limit quantitative extrapolation.",
    "L4 solubility records are mostly for unrelated chemotypes; only physostigmine solubility (C64) is partially relevant but does not resolve the threshold question."
  ],
  "decision_summary": "Prediction remains low: the query is a quaternary ammonium iboga-type alkaloid with an N-methyl indoline; direct low-F outcomes from ipratropium (2-3%), physostigmine (1-5%, 3% oral solution), lisuride (~10%, 10-20%), and pentazocine (18%, 0.18 ± 0.05) affirmatively support F < 20%. L3 exposure records and L4 solubility/dissolution records are mostly unrelated; C64 shows physostigmine is highly soluble but does not change the low-F assessment. Confidence is moderate because no direct query-specific bioavailability data are available and the explicit quaternary charge conflicts with the computed neutral fraction."
}

